#include <bits/stdc++.h>
using namespace std;

const long long MODULUS = 998244353;
vector<long long> wPre, wPreInv;

long long powMod(long long base, int exp) {
    long long res = 1;
    long long b = base;
    int e = exp;
    while (e > 0) {
        if (e & 1) res = (res * b) % MODULUS;
        b = (b * b) % MODULUS;
        e >>= 1;
    }
    return res;
}

void prepareRoots() {
    wPre.resize(21);
    wPreInv.resize(21);
    for (int h = 0; h <= 20; h++) {
        wPre[h] = powMod(3, (MODULUS - 1) >> h);
        wPreInv[h] = powMod(3, (MODULUS - 1) - ((MODULUS - 1) >> h));
    }
}

void fftTransform(vector<long long>& data, int len, bool inv) {
    for (int i = 1, j = 0; i < len; i++) {
        int mask = len;
        do {
            j ^= mask >>= 1;
        } while ((j & mask) == 0);
        if (i < j) {
            swap(data[i], data[j]);
        }
    }
    for (int h = 0, size; (size = 1 << h) < len; h++) {
        long long root = inv ? wPreInv[h + 1] : wPre[h + 1];
        for (int startIdx = 0; startIdx < len; startIdx += size * 2) {
            long long w = 1;
            for (int j = 0; j < size; j++) {
                int leftIdx = startIdx + j, rightIdx = leftIdx + size;
                long long u = data[leftIdx], v = data[rightIdx] * w % MODULUS;
                data[leftIdx] = (u + v) % MODULUS;
                data[rightIdx] = (u - v + MODULUS) % MODULUS;
                w = (w * root) % MODULUS;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    prepareRoots();

    int nHalfVal, kCount;
    cin >> nHalfVal >> kCount;

    int sizeN = 1;
    while (sizeN < nHalfVal * 9 + 1) sizeN <<= 1;

    vector<long long> arrayData(sizeN, 0);
    for (int i = 0; i < kCount; i++) {
        int d;
        cin >> d;
        arrayData[d] = 1;
    }

    fftTransform(arrayData, sizeN, false);
    for (int i = 0; i < sizeN; i++) {
        arrayData[i] = powMod(arrayData[i], nHalfVal);
    }
    fftTransform(arrayData, sizeN, true);

    long long invN = powMod(sizeN, MODULUS - 2);
    for (int i = 0; i < sizeN; i++) {
        arrayData[i] = (arrayData[i] * invN) % MODULUS;
    }

    long long totalSum = 0;
    for (int i = 0; i <= nHalfVal * 9; i++) {
        long long val = arrayData[i];
        totalSum = (totalSum + val * val) % MODULUS;
    }

    cout << totalSum << "\n";

    return 0;
}
